\begin{figure}[h!]
\includegraphics[width=0.48\textwidth]{fig4-ion_signal_vs_delay.pdf}
\caption{Mean ion signal in the $v=0$ state as a function of the time of flight, i.e. the delay between the opening of the pulsed valve and the REMPI laser pulse. Each data point is the average of 10 to 20 experimental sequences. Error bars represent the standard deviation. The backing pressure is 2 bar and the valve opening duration is estimated to be shorter than 10 $\mu$s. The dashed line is a fit by a Gaussian function with a FWHM of 35(2)~$\mu$s.}\label{fig:delay}
