\title{Two-Dimensional Sideband Raman Cooling and Zeeman State
Preparation in an Optical Lattice
\footnote{Contribution of NIST, not subject to copyright}}

\author{A.V. Taichenachev, A.M. Tumaikin, and V.I. Yudin}

